use std::rc::Rc;use std::cell::RefCell;use std::collections::{VecDeque,BTreeMap};impl Solution{pub fn vertical_order(r:Option<Rc<RefCell<TreeNode>>>)->Vec<Vec<i32>>{let Some(root)=r else{return vec![]};let mut q=VecDeque::from([(root,0)]);let mut m:BTreeMap<i32,Vec<i32>>=BTreeMap::new();while let Some((n,c))=q.pop_front(){let b=n.borrow();m.entry(c).or_default().push(b.val);if let Some(x)=b.left.clone(){q.push_back((x,c-1))}if let Some(x)=b.right.clone(){q.push_back((x,c+1))}}m.into_values().collect()}}
